import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`deep-research`,heroTitle:`Hours of research, one workflow.`,heroSubtitle:`Instead of one model trying to do everything, Computer delegates to specialized sub-agents that run in parallel—cutting hours of research into a single workflow.`,inputUrlCta:`Research my topic`,inputUrlPlaceholder:`e.g. research question, market, or campaign issue`,inputUrlPrefill:`Research {url} in depth. (1) Break the question into the key sub-questions and unknowns that need to be resolved. (2) Search broadly across primary and secondary sources, iterating until you have enough evidence on each angle. (3) Cross-check claims, flag contradictions, score source quality, and cite every important finding. (4) Synthesize the research into a structured report with clear conclusions, open questions, and recommended actions. (5) Include competitor insights, market context, and operational next steps where relevant.`,heroOverlaySteps:[`Decomposing the problem into sub-queries and search paths`,`Spinning up sub-agents to handle the task`,`Synthesizing findings into a structured, citation-backed report`,`Source-verified research with actionable recommendations — ready to review`],generatingSteps:[`Analyzing your question and identifying key dimensions`,`Spinning up sub-agents to research different things`,`Configuring multi-pass search loops with source verification and conflict resolution`,`Setting up structured output with citations, confidence scores, and next steps`],featureSectionTitle:`From question to verified research report`,featureCardTitles:[`Connects to your ads stack`,`Outputs you can trust`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Analytics, Google Sheets, Google Drive, Notion, Ahrefs — Computer plugs into your tools so research flows straight into your campaign planning workflow.`,`Structured research briefs. Source-cited findings. Competitor breakdowns. Audience insights. Bid strategy recommendations backed by data — not guesses.`],capabilitySectionTitle:`Your research analyst, on autopilot`,capabilitySectionSubtitle:`Ask your question, step away, come back to a fully sourced research report.`,capabilityCards:[{title:`Question Decomposition`,description:`Computer can break a complex question into sub-queries — targeting each angle separately so nothing gets missed.`},{title:`Exhaustive Search`,description:`Computer can run dozens of searches across multiple sources — iterating until it finds comprehensive, up-to-date data on your ads topic.`},{title:`Source Cross-Checking`,description:`Computer can verify claims across multiple sources — flagging contradictions, scoring confidence, and citing everything so you know what to trust.`},{title:`Connect Your Tools`,description:`Computer can push findings to Google Sheets, Google Drive, Notion, and Slack — so research lands where your team already works.`},{title:`Builds On Context`,description:`Computer can remember your goals, past research, and campaign goals — so every new question builds on what it already knows.`},{title:`Monitor & Alert`,description:`Computer can re-run research on a schedule and alert you when market conditions shift, new competitors emerge, or policies change.`}]});export{t as default};
